// post passes (VENDORED.md). The same as sgsr1_upscale.frag here (kept for reading and glslangValidator).
#pragma once

static const char sgsr1_upscale_frag[] =
    "#version 450\n"
    "// Snapdragon Game Super Resolution 1 (sgsr1_shader_mobile_edge_direction.frag, RGBA mode, UseEdgeDirection on).\n"
    "// Copyright (c) 2025, Qualcomm Innovation Center, Inc. SPDX-License-Identifier: BSD-3-Clause. Changed for\n"
    "// SavageWind: third_party/sgsr1/VENDORED.md.\n"
    "// t: the scene (linear light, render size). a = ViewportInfo (1 / input size, input size), b.xy = output size,\n"
    "// b.z = 1: the input is linear (taken to gamma 2.0 for the filter, as FSR 1's EASU does here, and back on output).\n"
    "layout(set = 0, binding = 0) uniform sampler2D ps0;\n"
    "layout(push_constant) uniform P { vec4 a; vec4 b; } pc;\n"
    "layout(location = 0) out vec4 out_Target0;\n"
    "#define OperationMode 1\n"
    "#define EdgeThreshold (8.0 / 255.0)\n"
    "#define EdgeSharpness 2.0\n"
    "vec4 enc(vec4 v) { return pc.b.z > 0.5 ? sqrt(max(v, vec4(0.0))) : v; }\n"
    "float fastLanczos2(float x) {\n"
    "    float wA = x - 4.0;\n"
    "    float wB = x * wA - wA;\n"
    "    wA *= wA;\n"
    "    return wB * wA;\n"
    "}\n"
    "vec2 weightY(float dx, float dy, float c, vec3 data) {\n"
    "    float std = data.x;\n"
    "    vec2 dir = data.yz;\n"
    "    float edgeDis = ((dx * dir.y) + (dy * dir.x));\n"
    "    float x = (((dx * dx) + (dy * dy)) + ((edgeDis * edgeDis) * ((clamp(((c * c) * std), 0.0, 1.0) * 0.7) + -1.0)));\n"
    "    float w = fastLanczos2(x);\n"
    "    return vec2(w, w * c);\n"
    "}\n"
    "vec2 edgeDirection(vec4 left, vec4 right) {\n"
    "    vec2 dir;\n"
    "    float RxLz = (right.x + (-left.z));\n"
    "    float RwLy = (right.w + (-left.y));\n"
    "    vec2 delta;\n"
    "    delta.x = (RxLz + RwLy);\n"
    "    delta.y = (RxLz + (-RwLy));\n"
    "    float lengthInv = inversesqrt((delta.x * delta.x + 3.075740e-05) + (delta.y * delta.y));\n"
    "    dir.x = (delta.x * lengthInv);\n"
    "    dir.y = (delta.y * lengthInv);\n"
    "    return dir;\n"
    "}\n"
    "void main() {\n"
    "    vec4 ViewportInfo = pc.a;\n"
    "    vec2 uv = gl_FragCoord.xy / pc.b.xy;\n"
    "    vec4 color;\n"
    "    color.xyz = enc(vec4(textureLod(ps0, uv, 0.0).xyz, 0.0)).xyz;\n"
    "    vec2 imgCoord = ((uv * ViewportInfo.zw) + vec2(-0.5, 0.5));\n"
    "    vec2 imgCoordPixel = floor(imgCoord);\n"
    "    vec2 coord = (imgCoordPixel * ViewportInfo.xy);\n"
    "    vec2 pl = (imgCoord + (-imgCoordPixel));\n"
    "    vec4 left = enc(textureGather(ps0, coord, OperationMode));\n"
    "    float edgeVote = abs(left.z - left.y) + abs(color[OperationMode] - left.y) + abs(color[OperationMode] - left.z);\n"
    "    if (edgeVote > EdgeThreshold) {\n"
    "        coord.x += ViewportInfo.x;\n"
    "        vec4 right = enc(textureGather(ps0, coord + vec2(ViewportInfo.x, 0.0), OperationMode));\n"
    "        vec4 upDown;\n"
    "        upDown.xy = enc(textureGather(ps0, coord + vec2(0.0, -ViewportInfo.y), OperationMode)).wz;\n"
    "        upDown.zw = enc(textureGather(ps0, coord + vec2(0.0, ViewportInfo.y), OperationMode)).yx;\n"
    "        float mean = (left.y + left.z + right.x + right.w) * 0.25;\n"
    "        left = left - vec4(mean);\n"
    "        right = right - vec4(mean);\n"
    "        upDown = upDown - vec4(mean);\n"
    "        color.w = color[OperationMode] - mean;\n"
    "        float sum = (((((abs(left.x) + abs(left.y)) + abs(left.z)) + abs(left.w)) + (((abs(right.x) + abs(right.y)) + abs(right.z)) + abs(right.w))) + (((abs(upDown.x) + abs(upDown.y)) + abs(upDown.z)) + abs(upDown.w)));\n"
    "        float sumMean = 1.014185e+01 / sum;\n"
    "        float std = (sumMean * sumMean);\n"
    "        vec3 data = vec3(std, edgeDirection(left, right));\n"
    "        vec2 aWY = weightY(pl.x, pl.y + 1.0, upDown.x, data);\n"
    "        aWY += weightY(pl.x - 1.0, pl.y + 1.0, upDown.y, data);\n"
    "        aWY += weightY(pl.x - 1.0, pl.y - 2.0, upDown.z, data);\n"
    "        aWY += weightY(pl.x, pl.y - 2.0, upDown.w, data);\n"
    "        aWY += weightY(pl.x + 1.0, pl.y - 1.0, left.x, data);\n"
    "        aWY += weightY(pl.x, pl.y - 1.0, left.y, data);\n"
    "        aWY += weightY(pl.x, pl.y, left.z, data);\n"
    "        aWY += weightY(pl.x + 1.0, pl.y, left.w, data);\n"
    "        aWY += weightY(pl.x - 1.0, pl.y - 1.0, right.x, data);\n"
    "        aWY += weightY(pl.x - 2.0, pl.y - 1.0, right.y, data);\n"
    "        aWY += weightY(pl.x - 2.0, pl.y, right.z, data);\n"
    "        aWY += weightY(pl.x - 1.0, pl.y, right.w, data);\n"
    "        float finalY = aWY.y / aWY.x;\n"
    "        float maxY = max(max(left.y, left.z), max(right.x, right.w));\n"
    "        float minY = min(min(left.y, left.z), min(right.x, right.w));\n"
    "        float deltaY = clamp(EdgeSharpness * finalY, minY, maxY) - color.w;\n"
    "        // smooth high contrast input\n"
    "        deltaY = clamp(deltaY, -23.0 / 255.0, 23.0 / 255.0);\n"
    "        color.x = clamp((color.x + deltaY), 0.0, 1.0);\n"
    "        color.y = clamp((color.y + deltaY), 0.0, 1.0);\n"
    "        color.z = clamp((color.z + deltaY), 0.0, 1.0);\n"
    "    }\n"
    "    out_Target0 = vec4(pc.b.z > 0.5 ? color.xyz * color.xyz : color.xyz, 1.0);\n"
    "}\n";
